public static String allRanges(int[] firsts, int[] seconds) {
    String s = "";
    for (int p = 0; p < firsts.length; p++) {
        int step = 1;
        if (seconds[p] < firsts[p]) {
            step = -1;   // בסדר יורד
        }
        int x = firsts[p];
        while (x != seconds[p]) {
            s = s + x + " ";
            x = x + step;
        }
        s = s + seconds[p] + "\n";
    }
    return s;
}

