System.out.println("סעיף א, בדיקה 2 (זוג אחד): " + check(allRanges(new int[] { 1 }, new int[] { 4 }), "1 2 3 4"));
System.out.println("סעיף א, בדיקה 3 (יורד ואחר כך עולה): " + check(allRanges(new int[] { 9, 2 }, new int[] { 6, 3 }), "9 8 7 6\n2 3"));
System.out.println("סעיף א, בדיקה 4 (מספרים שליליים): " + check(allRanges(new int[] { -2 }, new int[] { 1 }), "-2 -1 0 1"));

